    int tx = threadIdx.x, ty = threadIdx.y;

    // Each thread computes 2x2 elements
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    float sum00 = 0.0f, sum01 = 0.0f, sum10 = 0.0f, sum11 = 0.0f;

