__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    int bx = blockIdx.x * TILE_SIZE;
    int by = blockIdx.y * TILE_SIZE;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes a TILE_SIZE x TILE_SIZE block
    int row_start = by + ty * TILE_SIZE;
    int col_start = bx + tx * TILE_SIZE;

    // Register arrays for the output block
    float c[TILE_SIZE][TILE_SIZE];

    // Initialize output registers
    #pragma unroll
    for (int i = 0; i < TILE_SIZE; i++) {
        #pragma unroll
        for (int j = 0; j < TILE_SIZE; j++) {
            c[i][j] = 0.0f;
        }
    }

    // Compute the matrix multiplication
    for (int k = 0; k < N; k++) {
        // Load values from A and B
        float a[TILE_SIZE], b[TILE_SIZE];

        #pragma unroll
        for (int i = 0; i < TILE_SIZE; i++) {
            int row = row_start + i;
            a[i] = (row < N && k < N) ? A[row * N + k] : 0.0f;
        }

        #pragma unroll
        for (int j = 0; j < TILE_SIZE; j++) {
            int col = col_start + j;
            b[j] = (k < N && col < N) ? B[k * N + col] : 0.0f;
        }

        // Compute outer product
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; i++) {
            #pragma unroll
            for (int j = 0; j < TILE_SIZE; j++) {
                c[i][j] += a[i] * b[j];
            }
        }
    }

    // Store results
    #pragma unroll
    for (int i = 0; i < TILE_SIZE; i++) {
